  "dialectProfile": {
    "name": "Eritrean / Asmara Tigrinya",
    "scope": "This course now treats Eritrean/Asmara Tigrinya as the default classroom variety, using everyday Eritrean forms first rather than mixing regional alternatives as equal beginner answers.",
    "spellingPolicy": "The app prioritizes modern everyday fidel forms common in Eritrean teaching contexts. Historical or less common fidel variants are mentioned only as recognition notes, not as required beginner material.",
    "phrasePolicy": "Core greetings and short dialogues use Asmara-friendly forms such as ሰላም, ከመይ ኣለኻ/ኣለኺ, ደሓን ኣለኹ, የቐንየለይ, በጃኻ/በጃኺ, ደሓን ኩን/ኩኒ, and ይቕሬታ. Beginner request tasks now use a consistent item/help + please order first, with a note that native-speaker review should confirm naturalness and alternatives.",
    "outOfScope": "Tigray/Ethiopian regional alternatives, church/liturgical register, and highly formal written style are not taught as main-path answers in this version.",
    "nativeReviewNote": "Because no static site can fully resolve local usage, the course still needs review by fluent Eritrean/Asmara speakers before being treated as final teaching material.",
    "requestOrderPolicy": "For beginner controlled practice, the default chunk order is item/help + please: ማይ በጃኻ/በጃኺ, መግቢ በጃኻ/በጃኺ, ሓገዝ በጃኻ/በጃኺ, or ሓግዘኒ በጃኻ/በጃኺ. Real-life order and politeness can vary, so this is a scaffold, not a final naturalness claim."
  },
