          "type": "concept",
          "title": "The three-question routine",
          "reviewStatus": "draft",
          "body": "When you see a fidel character, ask three questions: 1) Which family shape is it? 2) Which of the seven orders is it? 3) What word or phrase is it helping build? This routine is the systematic path from character recognition to reading.",
